/// <summary>
/// Bug 397416: UAT - Demand - Error on manual claims when assigning tax invoice PBMSSIT
/// </summary>
[ExtensionOf(formStr(SalesCopying))]
internal final class METSalesCopyingFrm_Extension
{
}

Method.Source:
/// <summary>
/// For find sales order from all return orders, a customisation is already added to update METSalesTable
/// but is not reflected in the UI, then when user tries to update original tax invoice, the old record is updated and causing error.
/// </summary>
public void closeOk()
{
    METSalesTable metSalesTable;

    next closeOk();

    if (calledFromReturnTable && this.args().menuItemName() == menuitemDisplayStr(ReturnFindSalesOrder))
    {
        FormRun caller = this.args().caller();
        FormDataSource callerDS = caller.dataSource(formDataSourceStr(ReturnTable, SalesTable));

        metSalesTable = metSalesTable::findByRefRecId(callerDS.cursor().RecId);

        if (metSalesTable.RecId
            && metSalesTable.OriginalInvoice)
        {
            ttsbegin;
            METReturnOrderCopyChargesHelper::copySOHeaderCharges(metSalesTable, callerDS.cursor());
            ttscommit;
        }

        callerDS.research(true);
    }
}
